def overlap_half(g):
    h,w=len(g),len(g[0])
    # find vertical divider: column fully uniform non-zero
    div=None
    for j in range(w):
        col={g[i][j] for i in range(h)}
        if len(col)==1 and 0 not in col: div=j; break
    if div is not None:
        A=[r[:div] for r in g]; B=[r[div+1:] for r in g]
    else:
        for i in range(h):
            row={g[i][j] for j in range(w)}
            if len(row)==1 and 0 not in row: div=i; break
        A=g[:div]; B=g[div+1:]
    return [[2 if a!=0 and b!=0 else 0 for a,b in zip(ra,rb)] for ra,rb in zip(A,B)]
