from collections import Counter
def split_halves(g):
    h,w=len(g),len(g[0])
    flat=Counter(v for r in g for v in r)
    mode=flat.most_common(1)[0][0]
    for j in range(w):
        col={g[i][j] for i in range(h)}
        if len(col)==1 and 0 not in col and next(iter(col))!=mode:
            return [r[:j] for r in g],[r[j+1:] for r in g],True
    for i in range(h):
        row={g[i][j] for j in range(w)}
        if len(row)==1 and 0 not in row and next(iter(row))!=mode:
            return g[:i],g[i+1:],False
    return None
def overlap_half(g):
    A,B,_=split_halves(g)
    return [[2 if a!=0 and b!=0 else 0 for a,b in zip(ra,rb)] for ra,rb in zip(A,B)]
